edits.newText:
const value = source[prop]
if (state.finalized_ || !isDraftable(value)) {
	return value
}

// If value is already a draft proxy, return it directly
if (isDraft(value)) {
	return value
}

// If value is the same as base, or it's a draftable value that wasn't explicitly
// assigned (e.g., it was reordered via sort/reverse), we need to create a proxy.
// This handles the case where array elements were moved to different positions
// - the copy has the same object references as base, just in different order.
if (value === peek(state.base_, prop)) {
	prepareCopy(state)
	// Ensure array keys are always numbers
	const childKey = state.type_ === ArchType.Array ? +(prop as string) : prop
	const childDraft = createProxy(state.scope_, value, state, childKey)

	return (state.copy_![childKey] = childDraft)
}

// Value is different from base and not a draft - this happens after sort/reverse
// when elements were reordered. We still need a proxy for copy-on-write.
prepareCopy(state)
const childKey = state.type_ === ArchType.Array ? +(prop as string) : prop
const childDraft = createProxy(state.scope_, value, state, childKey)
return (state.copy_![childKey] = childDraft)

