import { produce, produceWithPatches, enablePatches } from "../src/immer";

enablePatches();

describe("array reverse/sort regression", () => {
  test("reverse + mutate should not mutate base", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    // next should be [{v: 999}, {v: 2}, {v: 1}] (reversed and first mutated)
    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    // base should be untouched
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("sort + mutate should not mutate base", () => {
    const base = [{v: 3}, {v: 1}, {v: 2}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.sort((a, b) => a.v - b.v);
      draft[0].v = 999;
    });

    // next should be [{v: 999}, {v: 2}, {v: 3}] (sorted then first mutated)
    expect(next).toEqual([{v: 999}, {v: 2}, {v: 3}]);

    // base should be untouched
    expect(base).toEqual([{v: 3}, {v: 1}, {v: 2}]);
  });

  test("reverse + mutate should produce correct patches", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const [next, patches, inversePatches] = produceWithPatches(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    // Applying inverse patches should restore base
    let restored = next;
    for (const patch of inversePatches) {
      restored = produce(restored, (draft: any) => {
        let target: any = draft;
        for (let i = 0; i < patch.path.length - 1; i++) {
          target = target[patch.path[i]];
        }
        const lastKey = patch.path[patch.path.length - 1];
        if (patch.op === "replace") {
          target[lastKey] = patch.value;
        } else if (patch.op === "add") {
          target[lastKey] = patch.value;
        } else if (patch.op === "remove") {
          delete target[lastKey];
        }
      });
    }
    expect(restored).toEqual(base);
  });

  test("reverse only + no mutation should produce no patches", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.reverse();
    });

    // Since reverse doesn't change values (just order), and we don't track order...
    // The result should reflect the reverse
    expect(next).toEqual([{v: 3}, {v: 2}, {v: 1}]);
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("sort + mutate specific elements", () => {
    const base = [3, 1, 4, 1, 5, 9, 2, 6] as number[];

    const next = produce(base, (draft) => {
      draft.sort((a, b) => a - b);
      // After sort: [1, 1, 2, 3, 4, 5, 6, 9]
      draft[0] = 100;
      draft[7] = 200;
    });

    expect(next).toEqual([100, 1, 2, 3, 4, 5, 6, 200]);
    expect(base).toEqual([3, 1, 4, 1, 5, 9, 2, 6]);
  });

  test("reverse of shallow objects + mutate should not corrupt base", () => {
    const obj1 = {v: 1};
    const obj2 = {v: 2};
    const obj3 = {v: 3};
    const base = [obj1, obj2, obj3];

    const next = produce(base, (draft) => {
      draft.reverse();
      // After reverse, draft[0] is the original obj3 (but as draft)
      // Mutating draft[0] should not touch obj3
      draft[0].v = 999;
    });

    expect(next[0].v).toBe(999);
    expect(next[1].v).toBe(2);
    expect(next[2].v).toBe(1);

    // obj3 (the original object at index 2) should NOT be mutated
    expect(obj3.v).toBe(3);
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("sort comparator accessing draft elements should work correctly", () => {
    const base = [{v: 3}, {v: 1}, {v: 2}] as {v: number}[];

    const next = produce(base, (draft) => {
      // Sort by value - comparator receives base values (not drafts)
      draft.sort((a, b) => a.v - b.v);
    });

    expect(next).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("chained reverse + sort + mutate", () => {
    const base = [{v: 3}, {v: 1}, {v: 2}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.reverse(); // [{v: 2}, {v: 1}, {v: 3}]
      draft.sort((a, b) => a.v - b.v); // [{v: 1}, {v: 2}, {v: 3}]
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 3}]);
    expect(base).toEqual([{v: 3}, {v: 1}, {v: 2}]);
  });

  test("reverse + push + mutate", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.reverse(); // [{v: 3}, {v: 2}, {v: 1}]
      draft.push({v: 4}); // [{v: 3}, {v: 2}, {v: 1}, {v: 4}]
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}, {v: 4}]);
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("original base state object references should not be mutated", () => {
    const obj1 = {v: 1};
    const obj2 = {v: 2};
    const base = [obj1, obj2];

    const next = produce(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    // obj2 (now at index 0 after reverse) should not have been mutated
    expect(obj2.v).toBe(2);
    // obj1 (now at index 1 after reverse) should not have been mutated
    expect(obj1.v).toBe(1);
  });

  test("reverse without mutations should not produce a new array", () => {
    const base = [1, 2, 3];

    const next = produce(base, (draft) => {
      draft.reverse();
    });

    // reverse doesn't actually create a "change" since immer doesn't track order
    // But we should still get the reversed result
    expect(next).toEqual([3, 2, 1]);
  });
});

import { describe, test, expect } from "vitest";
import { produce, produceWithPatches, enablePatches, enableArrayMethods } from "../src/immer";

enablePatches();
enableArrayMethods();

describe("array reverse/sort regression - detailed", () => {
  test("primitive array reverse + mutate", () => {
    const base = [1, 2, 3];
    const next = produce(base, (draft) => {
      draft.reverse(); // [3, 2, 1]
      draft[0] = 999; // [999, 2, 1]
    });
    expect(next).toEqual([999, 2, 1]);
    expect(base).toEqual([1, 2, 3]);
  });

  test("primitive array sort + mutate", () => {
    const base = [3, 1, 2];
    const next = produce(base, (draft) => {
      draft.sort((a, b) => a - b); // [1, 2, 3]
      draft[0] = 999; // [999, 2, 3]
    });
    expect(next).toEqual([999, 2, 3]);
    expect(base).toEqual([3, 1, 2]);
  });

  test("object array reverse + mutate element - check original reference", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}];

    // We track all objects in the base
    const originalObj0 = base[0];
    const originalObj1 = base[1];
    const originalObj2 = base[2];

    const next = produce(base, (draft) => {
      draft.reverse(); // [obj3, obj2, obj1]
      draft[0].v = 999;
    });

    // After reverse: next should be [{v: 999}, {v: 2}, {v: 1}]
    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    // Original objects should not be mutated
    expect(originalObj0.v).toBe(1);
    expect(originalObj1.v).toBe(2);
    expect(originalObj2.v).toBe(3);
  });

  test("sort + mutate with patches - patches should correctly describe changes", () => {
    const base = [{v: 3}, {v: 1}, {v: 2}];

    const [next, patches] = produceWithPatches(base, (draft) => {
      draft.sort((a, b) => a.v - b.v);
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 3}]);

    console.log("Patches:", JSON.stringify(patches));

    // Applying patches to base should produce next
    let patched: any = JSON.parse(JSON.stringify(base));
    for (const patch of patches) {
      let target = patched;
      for (let i = 0; i < patch.path.length - 1; i++) {
        target = target[patch.path[i]];
      }
      const lastKey = patch.path[patch.path.length - 1];
      if (patch.op === "replace") {
        target[lastKey] = patch.value;
      } else if (patch.op === "add") {
        if (Array.isArray(target)) {
          target.splice(Number(lastKey), 0, patch.value);
        } else {
          target[lastKey] = patch.value;
        }
      } else if (patch.op === "remove") {
        if (Array.isArray(target)) {
          target.splice(Number(lastKey), 1);
        } else {
          delete target[lastKey];
        }
      }
    }
    expect(patched).toEqual(next);
  });

  test("reverse + mutate - patches should correctly describe changes", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}];

    const [next, patches] = produceWithPatches(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    console.log("Reverse patches:", JSON.stringify(patches));
  });

  test("empty array reverse", () => {
    const base: number[] = [];
    const next = produce(base, (draft) => {
      draft.reverse();
    });
    expect(next).toEqual([]);
  });

  test("single element reverse + mutate", () => {
    const base = [{v: 1}];
    const next = produce(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });
    expect(next).toEqual([{v: 999}]);
    expect(base[0].v).toBe(1);
  });

  test("sort - native sort is stable?", () => {
    // Test that sort with same keys maintains order
    const base = [{v: 1, id: 'a'}, {v: 1, id: 'b'}, {v: 2, id: 'c'}];
    const next = produce(base, (draft) => {
      draft.sort((a, b) => a.v - b.v);
    });
    // After sort, items with same v should maintain relative order
    expect(next[0].v).toBe(1);
    expect(next[1].v).toBe(1);
    expect(next[2].v).toBe(2);
  });

  test("reverse then sort should work", () => {
    const base = [3, 1, 4, 1, 5, 9, 2, 6];
    const next = produce(base, (draft) => {
      draft.reverse();
      draft.sort((a, b) => a - b);
    });
    expect(next).toEqual([1, 1, 2, 3, 4, 5, 6, 9]);
    expect(base).toEqual([3, 1, 4, 1, 5, 9, 2, 6]);
  });

  test("multiple mutations after sort", () => {
    const base = [5, 3, 1, 4, 2];
    const next = produce(base, (draft) => {
      draft.sort((a, b) => a - b);
      // After sort: [1, 2, 3, 4, 5]
      draft[0] = 10;
      draft[1] = 20;
      draft[2] = 30;
      draft[3] = 40;
      draft[4] = 50;
    });
    expect(next).toEqual([10, 20, 30, 40, 50]);
    expect(base).toEqual([5, 3, 1, 4, 2]);
  });

  test("reverse + mutate - multiple elements", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}, {v: 4}];
    const next = produce(base, (draft) => {
      draft.reverse(); // [{v:4}, {v:3}, {v:2}, {v:1}]
      draft[0].v = 10;
      draft[1].v = 20;
      draft[2].v = 30;
      draft[3].v = 40;
    });
    expect(next).toEqual([{v: 10}, {v: 20}, {v: 30}, {v: 40}]);
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}, {v: 4}]);
  });
});

